result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

# Active rows only (no cancelled)
cancelled_statuses = {'can','cancel','cancelled','canceled','void','voided','rejected'}
df_active = df[~df['row_kind'].isin(['cancel'])].copy()
